import sys
from collections import defaultdict

def count_ones(x):
    return bin(x).count('1')

def main():
    input = sys.stdin.read().strip().split()
    index = 0
    T = int(input[index])
    index += 1
    results = []
    for _ in range(T):
        Q = int(input[index])
        index += 1
        S = set()
        even_count = 0
        odd_count = 0
        for _ in range(Q):
            X = int(input[index])
            index += 1
            if X not in S:
                S.add(X)
                if count_ones(X) % 2 == 0:
                    even_count += 1
                else:
                    odd_count += 1
                new_elements = set()
                for y in S:
                    if y != X:
                        z = y ^ X
                        if z not in S:
                            new_elements.add(z)
                            if count_ones(z) % 2 == 0:
                                even_count += 1
                            else:
                                odd_count += 1
                S.update(new_elements)
            results.append(f"{even_count} {odd_count}")
    print("\n".join(results))

main()
